<?php
require_once __DIR__ . '/../config/db.php';
require_once __DIR__ . '/admincheck_role.php';
require_once __DIR__ . '/../config/permissions.php';

$allowedRoles = ['Super Admin','Admin','Assistant Manager','Senior Assistant Manager','Operations Manager','VP','Supervisor','Team Lead','WFM Executive','Finance Manager','Accountant','Employee'];
if (!in_array($admin_role, $allowedRoles, true)) { http_response_code(403); exit('Access denied.'); }

$adminId = (int)($_SESSION['admin_id'] ?? 0);
$message = ''; $error = '';
$canCreate = hasPermission($conn, 'requisitions', 'create');
$stages = [
    'assistant_manager' => ['Assistant Manager', ['Assistant Manager']],
    'senior_assistant_manager' => ['Senior Assistant Manager', ['Senior Assistant Manager']],
    'operations_manager' => ['Operations Manager', ['Operations Manager']],
    'vp' => ['VP', ['VP']],
    'executive' => ['CEO / MD', ['CEO','CEO / Managing Director','Managing Director','MD','Super Admin','Admin']],
];
$people=[]; $aq=mysqli_query($conn,'SELECT id,name,role FROM admin ORDER BY name'); while($a=mysqli_fetch_assoc($aq)) $people[]=$a;
$stagePeople=[]; foreach($stages as $key=>[$label,$roles]) $stagePeople[$key]=array_values(array_filter($people,fn($p)=>in_array($p['role'],$roles,true)));
$missingReviewerRoles=[]; foreach($stages as $key=>[$label]) if(empty($stagePeople[$key])) $missingReviewerRoles[]=$label;
$workflowReady=empty($missingReviewerRoles);

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    ems_verify_csrf();
    try {
        $action = $_POST['action'] ?? '';
        if ($action === 'create') {
            if (!$canCreate) throw new RuntimeException('You do not have permission to open a requisition.');
            if (!$workflowReady) throw new RuntimeException('Configure all approval roles before opening a requisition. Missing: '.implode(', ',$missingReviewerRoles).'.');
            $job=trim($_POST['job_title']??''); $dept=trim($_POST['department']??''); $justification=trim($_POST['justification']??'');
            $requirements=trim($_POST['requirements']??''); $positions=max(1,(int)($_POST['positions']??1));
            $type=trim($_POST['employment_type']??'Permanent'); $requiredBy=trim($_POST['required_by']??''); $priority=$_POST['priority']??'Medium';
            if ($job==='' || $dept==='' || $justification==='') throw new RuntimeException('Please complete all required requisition fields.');
            if (!in_array($type,['Permanent','Full Time','Part Time','Contract','Probation','Internship','Consultant'],true)) $type='Permanent';
            if (!in_array($priority,['Low','Medium','High','Urgent'],true)) $priority='Medium';
            $assignTo=(int)($_POST['assign_to']??0);
            if (!$assignTo) throw new RuntimeException('Please select a person in Assign To.');
            $p=mysqli_prepare($conn,"SELECT id,name,role FROM admin WHERE id=? AND role='Assistant Manager' LIMIT 1"); mysqli_stmt_bind_param($p,'i',$assignTo); mysqli_stmt_execute($p);
            $firstAssignee=mysqli_fetch_assoc(mysqli_stmt_get_result($p));
            if (!$firstAssignee) throw new RuntimeException('The first reviewer must be an Assistant Manager.');
            mysqli_begin_transaction($conn);
            $status='Pending Assistant Manager';
            $q=mysqli_prepare($conn,"INSERT INTO employee_requisitions (job_title,department,positions,employment_type,required_by,justification,requirements,priority,requested_by,requested_by_name,requested_by_role,status) VALUES (?,?,?,?,NULLIF(?,''),?,?,?,?,?,?,?)");
            mysqli_stmt_bind_param($q,'ssisssssisss',$job,$dept,$positions,$type,$requiredBy,$justification,$requirements,$priority,$adminId,$admin_name,$admin_role,$status); mysqli_stmt_execute($q);
            $reqId=mysqli_insert_id($conn); $order=0;
            foreach ($stages as $key => [$label,$roles]) { $order++; $person=$order===1?$firstAssignee:($stagePeople[$key][0]??['id'=>0,'name'=>$label.' Queue']); $stepStatus=$order===1?'Pending':'Waiting';
                $s=mysqli_prepare($conn,'INSERT INTO employee_requisition_approvals (requisition_id,step_order,stage_key,stage_label,approver_id,approver_name,status) VALUES (?,?,?,?,?,?,?)');
                mysqli_stmt_bind_param($s,'iississ',$reqId,$order,$key,$label,$person['id'],$person['name'],$stepStatus); mysqli_stmt_execute($s);
            }
            mysqli_commit($conn); $message='Requisition opened and sent to the Assistant Manager.';
        } elseif ($action === 'delete') {
            if ($admin_role !== 'Super Admin' || !hasPermission($conn, 'requisitions', 'delete')) throw new RuntimeException('Only Super Admin can remove a requisition.');
            $reqId=(int)($_POST['id']??0);
            if (!$reqId) throw new RuntimeException('Invalid requisition.');
            $d=mysqli_prepare($conn,'DELETE FROM employee_requisitions WHERE id=?');
            mysqli_stmt_bind_param($d,'i',$reqId); mysqli_stmt_execute($d);
            if (mysqli_stmt_affected_rows($d)<1) throw new RuntimeException('Requisition not found.');
            $message='Requisition removed successfully.';
        } elseif ($action === 'decision') {
            if (!hasPermission($conn, 'requisitions', 'approve')) throw new RuntimeException('You do not have permission to approve requisitions.');
            $reqId=(int)($_POST['id']??0); $decision=$_POST['decision']??''; $comment=trim($_POST['comment']??'');
            if (!in_array($decision,['Approved','Rejected'],true)) throw new RuntimeException('Invalid decision.');
            mysqli_begin_transaction($conn);
            $q=mysqli_prepare($conn,"SELECT * FROM employee_requisition_approvals WHERE requisition_id=? AND status='Pending' FOR UPDATE");
            mysqli_stmt_bind_param($q,'i',$reqId); mysqli_stmt_execute($q); $step=mysqli_fetch_assoc(mysqli_stmt_get_result($q));
            if (!$step) throw new RuntimeException('This requisition has no pending approval.');
            $stageRoles=$stages[$step['stage_key']][1]??[];
            $roleCanReview=in_array($admin_role,$stageRoles,true) || ($step['stage_key']==='executive' && in_array($admin_role,['Super Admin','Admin'],true));
            if ($admin_role!=='Super Admin' && ((int)$step['approver_id']>0 ? (int)$step['approver_id']!==$adminId : !$roleCanReview)) throw new RuntimeException('This requisition is not assigned to you for approval.');
            $u=mysqli_prepare($conn,'UPDATE employee_requisition_approvals SET status=?,comment=?,acted_at=NOW() WHERE id=?');
            mysqli_stmt_bind_param($u,'ssi',$decision,$comment,$step['id']); mysqli_stmt_execute($u);
            if ($decision==='Rejected') {
                $status='Rejected by '.$step['stage_label'];
            } else {
                $nextOrder=(int)$step['step_order']+1;
                $n=mysqli_prepare($conn,"UPDATE employee_requisition_approvals SET status='Pending' WHERE requisition_id=? AND step_order=?");
                mysqli_stmt_bind_param($n,'ii',$reqId,$nextOrder); mysqli_stmt_execute($n);
                $status=mysqli_stmt_affected_rows($n)>0 ? 'Pending '.($nextOrder===2?'Senior Assistant Manager':($nextOrder===3?'Operations Manager':($nextOrder===4?'VP':'CEO / MD'))) : 'Approved';
            }
            $r=mysqli_prepare($conn,'UPDATE employee_requisitions SET status=? WHERE id=?'); mysqli_stmt_bind_param($r,'si',$status,$reqId); mysqli_stmt_execute($r);
            mysqli_commit($conn); $message='Your review has been saved.';
        }
    } catch (Throwable $e) { try { mysqli_rollback($conn); } catch(Throwable $ignored){} $error=$e->getMessage(); }
}

$roleStage=['Assistant Manager'=>'assistant_manager','Senior Assistant Manager'=>'senior_assistant_manager','Operations Manager'=>'operations_manager','VP'=>'vp','Super Admin'=>'executive','Admin'=>'executive'];
$queueClause=isset($roleStage[$admin_role]) ? " OR EXISTS (SELECT 1 FROM employee_requisition_approvals queue_step WHERE queue_step.requisition_id=r.id AND queue_step.approver_id=0 AND queue_step.status='Pending' AND queue_step.stage_key='".mysqli_real_escape_string($conn,$roleStage[$admin_role])."')" : '';
$where=in_array($admin_role,['Super Admin','Admin'],true)?'1=1':('(r.requested_by='.$adminId.' OR EXISTS (SELECT 1 FROM employee_requisition_approvals mine WHERE mine.requisition_id=r.id AND mine.approver_id='.$adminId.')'.$queueClause.')');
$rq=mysqli_query($conn,"SELECT r.* FROM employee_requisitions r WHERE $where ORDER BY r.id DESC"); $rows=[];
while($r=mysqli_fetch_assoc($rq)){ $s=mysqli_prepare($conn,'SELECT * FROM employee_requisition_approvals WHERE requisition_id=? ORDER BY step_order'); mysqli_stmt_bind_param($s,'i',$r['id']); mysqli_stmt_execute($s); $r['steps']=mysqli_fetch_all(mysqli_stmt_get_result($s),MYSQLI_ASSOC); $rows[]=$r; }
$counts=['Open'=>0,'Awaiting Me'=>0,'Approved'=>0,'Rejected'=>0]; foreach($rows as $r){ if($r['status']==='Approved')$counts['Approved']++; elseif(str_starts_with($r['status'],'Rejected'))$counts['Rejected']++; else $counts['Open']++; foreach($r['steps'] as $s)if($s['status']==='Pending'&&(int)$s['approver_id']===$adminId)$counts['Awaiting Me']++; }
?>
