<style>.req-card{background:#fff;border:1px solid #e2e8f0;border-radius:16px;box-shadow:0 1px 3px #00000012}.approval-flow{display:flex;align-items:flex-start;min-width:760px}.step{width:125px;text-align:center;font-size:11px;position:relative}.step .dot{width:30px;height:30px;margin:auto;border-radius:50%;display:grid;place-items:center;background:#e2e8f0;color:#64748b}.step.approved .dot{background:#dcfce7;color:#15803d}.step.pending .dot{background:#dbeafe;color:#1d4ed8;box-shadow:0 0 0 4px #dbeafe80}.step.rejected .dot{background:#fee2e2;color:#dc2626}.connector{height:2px;flex:1;background:#e2e8f0;margin-top:15px}.badge-status{padding:6px 10px;border-radius:20px;font-size:11px}.dark-mode .req-card,.dark-mode .modal-content{background:#1e293b;color:#e2e8f0;border-color:#334155}</style></head><body>
