lass="fa fa-file-invoice-dollar"></i> Generate Payroll</a><a href="payroll_history.php" class="sidebar-link"><i class="fa fa-clock-rotate-left"></i> Payroll History</a><a href="salary_components.php" class="sidebar-link"><i class="fa fa-wallet"></i> Salary Components</a><a href="salary_slips.php" class="sidebar-link"><i class="fa fa-file-pdf"></i> Salary Slips</a><a href="payroll_reports.php" class="sidebar-link"><i class="fa fa-chart-line"></i> Payroll Reports</a><a href="salary_structure.php" class="sidebar-link"><i class="fa fa-money-bill-wave"></i> Salary Structure</a><a href="monthly_payroll.php" class="sidebar-link"><i class="fa fa-calendar"></i> Monthly Payroll</a></div><div class="sidebar-section-title">System</div><div class="sidebar-section-group"><a href="add_notice.php" class="sidebar-link"><i class="fa fa-bullhorn"></i> Notices</a><a href="add_holiday.php" class="sidebar-link"><i class="fa fa-plane"></i> Holidays</a><a href="send_email.php" class="sidebar-link"><i class="fa fa-envelope"></i> Send Email</a><?php if(in_array($admin_role,['Super Admin','Admin'],true)):?><a href="security_audit.php" class="sidebar-link"><i class="fa fa-shield-halved"></i> Security Audit</a><?php endif;?><a href="change_password.php" class="sidebar-link"><i class="fa fa-key"></i> Change Password</a><a href="logout.php" class="sidebar-link"><i class="fa fa-right-from-bracket"></i> Logout</a></div></nav></aside>
<div class="main-content" id="mainContent"><header class="header"><div class="header-left"><button class="sidebar-toggle" id="sidebarToggle"><i class="fa fa-bars"></i></button><h4>Employee Requisitions <span>/ Hiring Approval</span></h4></div><div class="header-right"><?php $darkModeInTopbar=true;include('../dark_mode.php');?><a href="logout.php" class="btn btn-danger btn-sm rounded-pill">Logout</a></div></header><div class="page-content">
<?php if($message):?><div class="alert alert-success"><?=htmlspecialchars($message)?></div><?php endif;?><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif;?>
<?php if($canCreate&&!$workflowReady):?><div class="alert alert-warning"><strong>Approval workflow is not ready.</strong> Create active admin accounts for: <?=htmlspecialchars(implode(', ',$missingReviewerRoles))?>.</div><?php endif;?>
<div class="d-flex flex-wrap justify-content-between align-items-center mb-4 gap-3"><div><h3 class="mb-1">Hiring Requisitions</h3><p class="text-muted mb-0">One assignment → Assistant Manager → Senior Assistant Manager → Operations Manager → VP → CEO / MD</p></div><?php if($canCreate&&$workflowReady):?><button class="btn btn-primary rounded-pill px-4" data-bs-toggle="modal" data-bs-target="#newReq"><i class="fa fa-plus me-2"></i>Open Requisition</button><?php endif;?></div>
<div class="row g-3 mb-4"><?php foreach($counts as $label=>$count):?><div class="col-6 col-lg-3"><div class="req-card p-3"><div class="text-muted small"><?=htmlspecialchars($label)?></div><div class="fs-3 fw-bold"><?=$count?></div></div></div><?php endforeach;?></div>
<div class="req-card overflow-hidden"><div class="table-responsive"><table class="table align-middle mb-0"><thead class="table-light"><tr><th class="p-3">Requisition</th><th>Position</th><th>Sequential Approval Flow</th><th>Status</th><th>Review</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="5" class="text-center text-muted py-5">No requisitions found.</td></tr><?php endif;?><?php foreach($rows as $r):?><tr><td class="p-3"><strong>#REQ-<?=str_pad($r['id'],4,'0',STR_PAD_LEFT)?></strong><br><small class="text-muted"><?=htmlspecialchars($r['requested_by_name'])?> · <?=htmlspecialchars($r['department'])?></small></td><td><strong><?=htmlspecialchars($r['job_title'])?></strong><br><small><?=intval($r['positions'])?> position(s)</small></td><td><div class="approval-flow"><?php foreach($r['steps'] as $i=>$s):?><?php if($i):?><span class="connector"></span><?php endif;?><span class="step <?=strtolower($s['status'])?>"><span class="dot"><i class="fa <?= $s['status']==='Approved'?'fa-check':($s['status']==='Rejected'?'fa-xmark':'fa-user')?>"></i></span><strong class="d-block mt-1"><?=htmlspecialchars($s['stage_label'])?></strong><span class="text-muted"><?=htmlspecialchars($s['approver_name'])?></span></span><?php endforeach;?></div></td><td><span class="badge badge-status bg-<?=$r['status']==='Approved'?'success':(str_starts_with($r['status'],'Rejected')?'danger':'warning')?>"><?=htmlspecialchars($r['status'])?></span></td><td><?php $mine=false;foreach($r['steps'] as $s){$queueMine=(int)$s['approver_id']===0&&isset($roleStage[$admin_role])&&$roleStage[$admin_role]===$s['stage_key'];if($s['status']==='Pending'&&((int)$s['approver_id']===$adminId||$queueMine))$mine=true;}$detailPayload=base64_encode(json_encode(['number'=>'REQ-'.str_pad($r['id'],4,'0',STR_PAD_LEFT),'job_title'=>$r['job_title'],'department'=>$r['department'],'positions'=>$r['positions'],'employment_type'=>$r['employment_type'],'required_by'=>$r['required_by']?:'Not specified','priority'=>$r['priority'],'requester'=>$r['requested_by_name'],'requester_role'=>$r['requested_by_role'],'created_at'=>date('d M Y, h:i A',strtotime($r['created_at'])),'justification'=>$r['justification'],'requirements'=>$r['requirements']?:'Not specified','status'=>$r['status'],'steps'=>$r['steps']],JSON_UNESCAPED_UNICODE));if($mine):?><button class="btn btn-sm btn-primary review-btn" data-bs-toggle="modal" data-bs-target="#decision" data-id="<?=$r['id']?>" data-details="<?=htmlspecialchars($detailPayload,ENT_QUOTES)?>">Review</button><?php else:?><button class="btn btn-sm btn-outline-secondary review-btn" data-bs-toggle="modal" data-bs-target="#decision" data-id="<?=$r['id']?>" data-details="<?=htmlspecialchars($detailPayload,ENT_QUOTES)?>" data-readonly="1">Details</button><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
<?php if($canCreate&&$workflowReady):?><div class="modal fade" id="newReq" tabindex="-1"><div class="modal-dialog modal-lg"><form method="post" class="modal-content"><div class="modal-header"><h5 class="modal-title">Open Employee Requisition</h5><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(ems_csrf_token())?>"><input type="hidden" name="action" value="create"><div class="row g-3"><div class="col-md-8"><label class="form-label">Job Title *</label><input name="job_title" class="form-control" required></div><div class="col-md-4"><label class="form-label">Positions *</label><input name="positions" type="number" min="1" value="1" class="form-control" required></div><div class="col-md-6"><label class="form-label">Department *</label><input name="department" class="form-control" required></div><div class="col-md-3"><label class="form-label">Employment Type</label><select name="employment_type" class="form-select"><option>Full Time</option><option>Part Time</option><option>Contract</option><option>Internship</option></select></div><div class="col-md-3"><label class="form-label">Required By</label><input name="required_by" type="date" class="form-control"></div><div class="col-md-4"><label class="form-label">Priority</label><select name="priority" class="form-select"><option>Low</option><option selected>Medium</option><option>High</option><option>Urgent</option></select></div><div class="col-md-8"><label class="form-label">Assign To *</label><select name="assign_to" class="form-select" required><option value="">Select Assistant Manager</option><?php foreach($stagePeople['assistant_manager'] as $p):?><option value="<?=$p['id']?>"><?=htmlspecialchars($p['name'].' — '.$p['role'])?></option><?php endforeach;?></select><small class="text-muted">The first reviewer must be an Assistant Manager. Remaining approvals follow the hierarchy automatically.</small></div><div class="col-12"><label class="form-label">Business Justification *</label><textarea name="justification" class="form-control" rows="3" required></textarea></div><div class="col-12"><label class="form-label">Skills / Requirements</label><textarea name="requirements" class="form-control" rows="3"></textarea></div></div></div><div class="modal-footer"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancel</button><button class="btn btn-primary">Open & Assign</button></div></form></div></div><?php endif;?>
<div class="modal fade" id="decision" tabindex="-1"><div class="modal-dialog modal-lg"><form method="post" class="modal-content"><div class="modal-header"><div><h5 class="modal-title">Review Requisition</h5><small class="text-muted" id="detailNumber"></small></div><button type="button" class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="csrf_token" value="<?=htmlspecialchars(ems_csrf_token())?>"><input type="hidden" name="action" value="decision"><input type="hidden" name="id" id="decisionId"><div class="req-card p-3 mb-3"><div class="row g-3"><div class="col-md-6"><small class="text-muted">Job Title</small><div class="fw-semibold" id="detailJob"></div></div><div class="col-md-3"><small class="text-muted">Department</small><div id="detailDepartment"></div></div><div class="col-md-3"><small class="text-muted">Priority</small><div id="detailPriority"></div></div><div class="col-md-3"><small class="text-muted">Positions</small><div id="detailPositions"></div></div><div class="col-md-3"><small class="text-muted">Employment Type</small><div id="detailType"></div></div><div class="col-md-3"><small class="text-muted">Required By</small><div id="detailRequired"></div></div><div class="col-md-3"><small class="text-muted">Submitted</small><div id="detailCreated"></div></div><div class="col-md-6"><small class="text-muted">Requested By</small><div id="detailRequester"></div></div><div class="col-md-6"><small class="text-muted">Current Status</small><div id="detailStatus"></div></div></div></div><div class="mb-3"><label class="form-label fw-semibold">Business Justification</label><div class="border rounded p-3 bg-light text-dark" id="detailJustification" style="white-space:pre-wrap"></div></div><div class="mb-3"><label class="form-label fw-semibold">Skills / Requirements</label><div class="border rounded p-3 bg-light text-dark" id="detailRequirements" style="white-space:pre-wrap"></div></div><div class="mb-3"><label class="form-label fw-semibold">Approval History</label><div id="detailHistory" class="list-group"></div></div><div id="decisionControls"><label class="form-label fw-semibold">Review Comment</label><textarea name="comment" class="form-control" rows="3" placeholder="Write your review comment..."></textarea></div></div><div class="modal-footer" id="decisionFooter"><button type="button" class="btn btn-light" data-bs-dismiss="modal">Cancel</button><button name="decision" value="Rejected" class="btn btn-outline-danger">Reject</button><button name="decision" value="Approved" class="btn btn-success">Approve & Forward</button></div></form></div></div>
<script src="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/js/bootstrap.bundle.min.js"></script><script>const s=document.getElementById('sidebar'),b=document.getElementById('sidebarBackdrop');document.getElementById('sidebarToggle').onclick=()=>{s.classList.toggle('open');b.classList.toggle('show')};document.getElementById('decision').addEventListener('show.bs.modal',e=>{const btn=e.relatedTarget,d=JSON.parse(decodeURIComponent(escape(atob(btn.dataset.details))));document.getElementById('decisionId').value=btn.dataset.id;document.getElementById('detailNumber').textContent='#'+d.number;document.getElementById('detailJob').textContent=d.job_title;document.getElementById('detailDepartment').textContent=d.department;document.getElementById('detailPriority').textContent=d.priority;document.getElementById('detailPositions').textContent=d.positions;document.getElementById('detailType').textContent=d.employment_type;document.getElementById('detailRequired').textContent=d.required_by;document.getElementById('detailCreated').textContent=d.created_at;document.getElementById('detailRequester').textContent=d.requester+' — '+d.requester_role;document.getElementById('detailStatus').textContent=d.status;document.getElementById('detailJustification').textContent=d.justification;document.getElementById('detailRequirements').textContent=d.requirements;document.getElementById('detailHistory').innerHTML='';d.steps.forEach(x=>{const item=document.createElement('div');item.className='list-group-item d-flex justify-content-between align-items-start';const left=document.createElement('div'),title=document.createElement('strong'),meta=document.createElement('small');title.textContent=x.stage_label+' — '+x.approver_name;meta.className='d-block text-muted';meta.textContent=x.comment?x.comment:(x.status==='Waiting'?'Waiting for previous approval':'No comment');left.append(title,meta);const badge=document.createElement('span');badge.className='badge bg-'+(x.status==='Approved'?'success':(x.status==='Rejected'?'danger':(x.status==='Pending'?'primary':'secondary')));badge.textContent=x.status;item.append(left,badge);document.getElementById('detailHistory').appendChild(item)});const readOnly=btn.dataset.readonly==='1';document.getElementById('decisionControls').style.display=readOnly?'none':'';document.getElementById('decisionFooter').querySelectorAll('[name="decision"]').forEach(x=>x.style.display=readOnly?'none':'');});</script></body></html>
